'use client';

import React, { useState, useRef } from 'react';
import { SignatureModal } from '@/components/modals/signature-modal';
import { Check, Search, Plus, Eye, Printer, CheckCircle2, Clock, AlertTriangle, X } from 'lucide-react';

interface CertificateRecord {
  id: string; employeeName: string; employeeCpf: string; sector: string;
  trainingName: string; trainingCode: string; completionDate: string;
  validityDate: string; daysRemaining: number; hours: number; score?: number;
  type: 'interno' | 'normativo'; provider?: string;
  status: 'Certificado' | 'Reciclar' | 'Vencido';
  programContent?: string[]; certificateHash: string;
}

const CERT_BG = "data:image/png;base64,";

const MOCK_CERTS: CertificateRecord[] = [];

function StatusBadge({ status }: { status: string }) {
  if (status === 'Certificado') return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200"><CheckCircle2 className="w-3 h-3"/>Certificado</span>;
  if (status === 'Reciclar') return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200"><Clock className="w-3 h-3"/>Reciclar</span>;
  return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200"><AlertTriangle className="w-3 h-3"/>Vencido</span>;
}

function CertificatePreview({ cert, onClose }: { cert: CertificateRecord; onClose: () => void }) {
  const printRef = useRef<HTMLDivElement>(null);
  const handlePrint = () => {
    const w = window.open('', '_blank');
    if (!w) return;
    w.document.write('<!DOCTYPE html><html><head><title>Certificado</title><style>@page{size:A4 landscape;margin:0}body{margin:0}</style></head><body>' + (printRef.current?.innerHTML||'')+'</body></html>');
    w.document.close();
    setTimeout(() => { w.print(); w.close(); }, 500);
  };
  return (
    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl max-w-5xl w-full overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between px-5 py-3 border-b border-slate-200">
          <span className="text-sm font-semibold text-slate-800">{cert.certificateHash} — {cert.employeeName}</span>
          <div className="flex items-center gap-2">
            <button onClick={handlePrint} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white text-xs font-medium rounded-lg hover:bg-blue-700"><Printer className="w-3.5 h-3.5"/>Imprimir / PDF</button>
            <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-slate-100"><X className="w-4 h-4 text-slate-500"/></button>
          </div>
        </div>
        <div className="overflow-auto max-h-[80vh] bg-slate-100 p-4">
          <div ref={printRef}>
            <div style={{width:'297mm',height:'210mm',position:'relative',fontFamily:'Arial,sans-serif',overflow:'hidden',marginBottom:'4px'}}>
              <img src={CERT_BG} style={{position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover'}} alt=""/>
              <div style={{position:'absolute',top:'12mm',right:'12mm',textAlign:'right',fontSize:'7.5px',color:'#111'}}>Tiger Rentank do Brasil Equipamentos Industriais LTDA<br/>CNPJ: 09.488.992/0002-01</div>
              <div style={{position:'absolute',top:'22mm',left:'68mm',right:'8mm',bottom:'8mm',display:'flex',flexDirection:'column',justifyContent:'center',padding:'0 12mm'}}>
                <div style={{fontSize:'22px',fontWeight:900,textAlign:'center',letterSpacing:'3px',color:'#111',marginBottom:'7mm'}}>CERTIFICADO</div>
                <div style={{fontSize:'9.5px',lineHeight:'1.9',color:'#111',textAlign:'center'}}>
                  Certificamos para os devidos fins que o colaborador<br/>
                  <strong style={{fontSize:'13px'}}>{cert.employeeName}</strong>,<br/>
                  portador do CPF <strong>{cert.employeeCpf}</strong> concluiu o treinamento em<br/>
                  <strong>{cert.trainingName}</strong><br/>
                  ministrado pela Tiger Rentank do Brasil Equipamentos LTDA<br/>
                  no dia <strong>{cert.completionDate}</strong>, totalizando <strong>{cert.hours} hora{cert.hours!==1?'s':''}</strong>.
                  {cert.score && <><br/><br/>Nota de aprovação: <strong style={{color:'#15803d'}}>{cert.score}%</strong></>}
                </div>
                <div style={{marginTop:'9mm',display:'flex',justifyContent:'space-around'}}>
                  {([['Diogo Sermoud','Responsável Técnico / Instrutor','Téc de Segurança do Trabalho','CREA: 2019109774'],['Luiz Felipe Nascimento','Assistente de QSMS','Tiger Rentank do Brasil','']] as string[][]).map(([name,r1,r2,r3])=>(
                    <div key={name} style={{textAlign:'center',fontSize:'7.5px',color:'#111'}}>
                      <div style={{borderTop:'1px solid #333',paddingTop:'2.5mm',width:'52mm'}}><strong>{name}</strong><br/>{r1}<br/>{r2}{r3?<><br/>{r3}</>:null}</div>
                    </div>
                  ))}
                </div>
                <div style={{marginTop:'3mm',textAlign:'center',fontSize:'6.5px',color:'#777'}}>Código: {cert.certificateHash} · Válido até: {cert.validityDate}</div>
              </div>
            </div>
            {cert.programContent && cert.programContent.length > 0 && (
              <div style={{width:'297mm',height:'210mm',position:'relative',fontFamily:'Arial,sans-serif',overflow:'hidden'}}>
                <img src={CERT_BG} style={{position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover'}} alt=""/>
                <div style={{position:'absolute',top:'22mm',left:'68mm',right:'8mm',bottom:'8mm',padding:'0 12mm'}}>
                  <div style={{fontSize:'15px',fontWeight:700,color:'#111',marginBottom:'3mm'}}>Conteúdo Programático</div>
                  <div style={{fontSize:'8.5px',color:'#555',marginBottom:'3mm'}}>Carga Horária: {cert.hours} hora{cert.hours!==1?'s':''}</div>
                  <ul style={{fontSize:'9.5px',lineHeight:'2.1',color:'#111',paddingLeft:'5mm'}}>{cert.programContent.map((item,i)=><li key={i}>{item}</li>)}</ul>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function RegisterModal({ onClose, onSave }: { onClose:()=>void; onSave:(c:CertificateRecord)=>void }) {
  const [f,setF]=useState({employeeName:'',employeeCpf:'',sector:'CS',trainingName:'',trainingCode:'',completionDate:'',hours:'8',provider:'REEF'});
  const s=(k:string,v:string)=>setF(p=>({...p,[k]:v}));
  const save=()=>{
    if(!f.employeeName||!f.trainingName||!f.completionDate)return;
    const d=new Date(f.completionDate.split('/').reverse().join('-'));
    const v=new Date(d);v.setFullYear(v.getFullYear()+2);
    const days=Math.floor((v.getTime()-Date.now())/86400000);
    onSave({id:`c-${Date.now()}`,...f,hours:parseInt(f.hours),validityDate:v.toLocaleDateString('pt-BR'),daysRemaining:days,type:'normativo',status:days<0?'Vencido':days<=60?'Reciclar':'Certificado',certificateHash:`CERT-${new Date().getFullYear()}-BR-${Math.floor(1000+Math.random()*9000)}`});
    onClose();
  };
  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg">
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-200">
          <span className="font-semibold text-slate-800">Registrar Treinamento Normativo</span>
          <button onClick={onClose}><X className="w-4 h-4 text-slate-400"/></button>
        </div>
        <div className="p-5 grid grid-cols-2 gap-3">
          {([['Colaborador','employeeName','col-span-2'],['CPF (ex: 000.000.000-00)','employeeCpf',''],['Setor','sector',''],['Treinamento','trainingName','col-span-2'],['Código (ex: NR-35)','trainingCode',''],['Fornecedor','provider',''],['Data (dd/mm/aaaa)','completionDate',''],['Carga horária (h)','hours','']] as [string,string,string][]).map(([label,key,cls])=>(
            <div key={key} className={`flex flex-col gap-1 ${cls}`}>
              <label className="text-xs font-medium text-slate-600">{label}</label>
              <input value={(f as any)[key]} onChange={e=>s(key,e.target.value)} className="h-9 px-3 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-400"/>
            </div>
          ))}
        </div>
        <div className="flex justify-end gap-2 px-5 pb-4">
          <button onClick={onClose} className="px-4 py-2 text-sm border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50">Cancelar</button>
          <button onClick={save} className="px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium">Salvar</button>
        </div>
      </div>
    </div>
  );
}

export function CertificatesScreen() {
  const [tab,setTab]=useState<'internos'|'normativos'>('internos');
  const [search,setSearch]=useState('');
  const [preview,setPreview]=useState<CertificateRecord|null>(null);
  const [showReg,setShowReg]=useState(false);
  const [signTarget,setSignTarget]=useState<CertificateRecord|null>(null);
  const [signatures,setSignatures]=useState<Record<string,string>>({});
  const [certs,setCerts]=useState<CertificateRecord[]>([]);
  const filtered=certs.filter(c=>c.type===(tab==='internos'?'interno':'normativo')&&(c.employeeName.toLowerCase().includes(search.toLowerCase())||c.trainingName.toLowerCase().includes(search.toLowerCase())));
  const internos=certs.filter(c=>c.type==='interno');
  const normativos=certs.filter(c=>c.type==='normativo');
  const vencidos=certs.filter(c=>c.status==='Vencido').length;
  return (
    <div className="p-6">
      <div className="grid grid-cols-4 gap-3 mb-5">
        {[{l:'Total',v:certs.length,c:'text-blue-600'},{l:'Internos (app)',v:internos.length,c:'text-purple-600'},{l:'Normativos (NRs)',v:normativos.length,c:'text-teal-600'},{l:'Vencidos',v:vencidos,c:'text-red-600'}].map(k=>(
          <div key={k.l} className="bg-white border border-slate-200 rounded-xl p-4">
            <div className="text-xs text-slate-500 mb-1">{k.l}</div>
            <div className={`text-2xl font-semibold ${k.c}`}>{k.v}</div>
          </div>
        ))}
      </div>
      <div className="flex items-center justify-between mb-4">
        <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
          {(['internos','normativos'] as const).map(t=>(
            <button key={t} onClick={()=>setTab(t)} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${tab===t?'bg-white text-slate-900 shadow-sm':'text-slate-500 hover:text-slate-700'}`}>
              {t==='internos'?`Internos (app) · ${internos.length}`:`Normativos (NRs) · ${normativos.length}`}
            </button>
          ))}
        </div>
        <div className="flex items-center gap-2">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400"/>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar colaborador ou treinamento..." className="pl-8 pr-3 h-9 border border-slate-200 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-400 w-64"/>
          </div>
          {tab==='normativos'&&<button onClick={()=>setShowReg(true)} className="flex items-center gap-1.5 px-3 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"><Plus className="w-3.5 h-3.5"/>Registrar Normativo</button>}
        </div>
      </div>
      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
        <table className="w-full text-sm">
          <thead><tr className="bg-slate-50 border-b border-slate-200">
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Colaborador</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Setor</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Treinamento</th>
            {tab==='internos'&&<th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Nota</th>}
            {tab==='normativos'&&<th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Fornecedor</th>}
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Conclusão</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Validade</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Dias</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Status</th>
            <th className="text-left px-4 py-3 text-xs font-medium text-slate-500">Ação</th>
          </tr></thead>
          <tbody>
            {filtered.length===0&&<tr><td colSpan={9} className="text-center py-10 text-slate-400 text-sm">Nenhum certificado encontrado</td></tr>}
            {filtered.map(c=>(
              <tr key={c.id} className="border-b border-slate-100 hover:bg-slate-50">
                <td className="px-4 py-3"><div className="font-medium text-slate-800 text-sm">{c.employeeName}</div><div className="text-xs text-slate-400 font-mono">{c.certificateHash}</div></td>
                <td className="px-4 py-3"><span className="px-2 py-0.5 bg-slate-100 text-slate-600 rounded-md text-xs">{c.sector}</span></td>
                <td className="px-4 py-3"><div className="font-medium text-slate-700 text-xs">{c.trainingName}</div><div className="text-xs text-blue-600 font-mono">{c.trainingCode}</div></td>
                {tab==='internos'&&<td className="px-4 py-3 font-semibold text-emerald-600">{c.score}%</td>}
                {tab==='normativos'&&<td className="px-4 py-3 text-xs text-slate-600">{c.provider}</td>}
                <td className="px-4 py-3 text-xs text-slate-500">{c.completionDate}</td>
                <td className="px-4 py-3 text-xs text-slate-500">{c.validityDate}</td>
                <td className="px-4 py-3 text-xs font-semibold"><span className={c.daysRemaining<0?'text-red-600':c.daysRemaining<=60?'text-amber-600':'text-emerald-600'}>{c.daysRemaining<0?`${c.daysRemaining}d`:`+${c.daysRemaining}d`}</span></td>
                <td className="px-4 py-3"><StatusBadge status={c.status}/></td>
                <td className="px-4 py-3"><div className="flex gap-1">
                  <button onClick={()=>setPreview(c)} className="p-1.5 rounded-lg border border-slate-200 hover:bg-blue-50 hover:border-blue-300 text-slate-500 hover:text-blue-600"><Eye className="w-3.5 h-3.5"/></button>
                  <button onClick={()=>setSignTarget(c)} title="Assinar" className="p-1.5 rounded-lg border border-slate-200 hover:bg-emerald-50 hover:border-emerald-300 text-slate-500 hover:text-emerald-600"><Check className="w-3.5 h-3.5"/></button>
                  <button onClick={()=>setPreview(c)} className="p-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 text-slate-500"><Printer className="w-3.5 h-3.5"/></button>
                </div></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {preview&&<CertificatePreview cert={preview} onClose={()=>setPreview(null)}/>}
      {signTarget&&<SignatureModal employeeName={signTarget.employeeName} trainingName={signTarget.trainingName} certificateHash={signTarget.certificateHash} onConfirm={(sig)=>{setSignatures(p=>({...p,[signTarget.id]:sig}));setSignTarget(null);}} onClose={()=>setSignTarget(null)}/>}
      {showReg&&<RegisterModal onClose={()=>setShowReg(false)} onSave={c=>setCerts(p=>[c,...p])}/>}
    </div>
  );
}
